const rows = (items[0].json.local_results || []).map(r => {
  const rf = [];
  if (!r.website) rf.push('no website');
  if (r.rating === undefined || r.rating < 4.0) rf.push('low rating');
  if (r.user_ratings_total === undefined || r.user_ratings_total < 20) rf.push('under 20 reviews');
  if (!r.thumbnail || !r.photos) rf.push('under 5 photos');
  if (r.business_status === 'UNCLAIMED' || r.claimed === false) rf.push('claim status');
  if (!r.current_opening_hours) rf.push('missing hours');
  if (!r.description) rf.push('weak description');
  return {
    business: r.name || '',
    trade: $('Webhook (trigger)').item.json.trade,
    town: $('Webhook (trigger)').item.json.town,
    contact: r.phone || (r.website ? r.website : ''),
    red_flags: rf.join(';'),
    outreach: '', replied: '', meeting: '', closed: '', setup: '', monthly: ''
  };
});
return rows.map(r => ({ json: r }));
